// Build-time accessors for the committed company-wise dataset
// (src/data/, generated by `npm run import:companies`). Frontmatter-only:
// importing this from a client <script> would ship ~1.5 MB of JSON.
//
// Loaded through import.meta.glob with explicit generics rather than plain
// JSON imports, so `astro check` doesn't infer a literal type for 1 300+
// problems.

import type {
  CompaniesIndex,
  CompanyFile,
  ProblemIndexEntry,
} from './company-problems';

const companyModules = import.meta.glob<CompanyFile | CompaniesIndex>('../data/companies/*.json', {
  eager: true,
  import: 'default',
});
const problemModules = import.meta.glob<Record<string, ProblemIndexEntry>>('../data/problems.json', {
  eager: true,
  import: 'default',
});

export const COMPANIES_INDEX = companyModules['../data/companies/index.json'] as CompaniesIndex;
export const PROBLEMS: Record<string, ProblemIndexEntry> =
  problemModules['../data/problems.json'] ?? {};

export const COMPANY_FILES: CompanyFile[] = COMPANIES_INDEX.companies.map((c) => {
  const f = companyModules[`../data/companies/${c.slug}.json`];
  if (!f || !('problems' in f)) throw new Error(`missing src/data/companies/${c.slug}.json`);
  return f;
});

/** company slug → display name. */
export const COMPANY_NAMES: Record<string, string> = Object.fromEntries(
  COMPANIES_INDEX.companies.map((c) => [c.slug, c.name]),
);

export const SOURCE = COMPANIES_INDEX.source;
